CREATE DATABASE IF NOT EXISTS tik_live_tools CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tik_live_tools;

CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(120) PRIMARY KEY, `value` TEXT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, tiktok_username VARCHAR(120) NULL, is_active TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS viewers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, unique_id VARCHAR(120) NOT NULL UNIQUE, display_name VARCHAR(180) NULL, avatar_url TEXT NULL, points DECIMAL(18,2) NOT NULL DEFAULT 0, level INT UNSIGNED NOT NULL DEFAULT 1, total_coins DECIMAL(18,2) NOT NULL DEFAULT 0, total_likes BIGINT UNSIGNED NOT NULL DEFAULT 0, first_seen_at TIMESTAMP NULL, last_seen_at TIMESTAMP NULL, INDEX idx_points(points), INDEX idx_coins(total_coins), INDEX idx_likes(total_likes));
CREATE TABLE IF NOT EXISTS live_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_type VARCHAR(60) NOT NULL, unique_id VARCHAR(120) NULL, display_name VARCHAR(180) NULL, gift_name VARCHAR(180) NULL, gift_id VARCHAR(80) NULL, coins DECIMAL(18,2) NOT NULL DEFAULT 0, quantity INT UNSIGNED NOT NULL DEFAULT 1, comment_text TEXT NULL, payload JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_event_type_created(event_type, created_at), INDEX idx_user_created(unique_id, created_at));
CREATE TABLE IF NOT EXISTS automation_rules (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, trigger_type VARCHAR(60) NOT NULL, trigger_config JSON NOT NULL, actions JSON NOT NULL, cooldown_seconds INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT INTO profiles (name, tiktok_username, is_active) VALUES ('Profil principal', NULL, 1) ON DUPLICATE KEY UPDATE name=VALUES(name);
